solution:
class MinStack:
    def __init__(self):
        self._items = []   # (value, smallest value in the stack up to and including it)

    def push(self, x):
        smallest = x if not self._items else min(x, self._items[-1][1])
        self._items.append((x, smallest))

    def pop(self):
        return self._items.pop()[0]

    def top(self):
        return self._items[-1][0]

    def get_min(self):
        return self._items[-1][1]
